package com.saney.renaultdocs

import android.annotation.SuppressLint
import android.app.Activity
import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.webkit.WebResourceRequest
import android.webkit.WebResourceResponse
import android.webkit.WebView
import android.webkit.WebViewClient
import android.widget.FrameLayout

/**
 * v0.5.130: «Інструкція користувача» inside the app (owner 2026-10-14: «як у Track
 * Catcher… вшити там, де про програму»). The page is assets/guide/index.html,
 * generated by docs/ua/user-guide/build_app_guide.py from the same source as
 * docs/ua/USER_GUIDE.md. Works offline.
 *
 * The page is served from an https asset origin by this client itself (no extra
 * library): Track Catcher found that file:// pages lost their images in WebView,
 * so both apps use the same https://appassets.androidplatform.net/assets/… path.
 * Home = list of sections; a tap opens one section; system «Назад» goes back
 * through the WebView history, then closes the screen.
 */
class GuideActivity : Activity() {
    private lateinit var web: WebView

    @SuppressLint("SetJavaScriptEnabled")
    override fun onCreate(
        savedInstanceState: Bundle?,
    ) {
        super.onCreate(
            savedInstanceState,
        )
        window.statusBarColor =
            Ui.background
        window.navigationBarColor =
            Ui.background

        web =
            WebView(this).apply {
                setBackgroundColor(
                    Ui.background,
                )
                // JavaScript only switches sections inside the local page.
                settings.javaScriptEnabled =
                    true
                settings.allowFileAccess =
                    false
                settings.allowContentAccess =
                    false
                webViewClient =
                    GuideClient(
                        this@GuideActivity,
                    )
            }

        val frame =
            FrameLayout(this).apply {
                setBackgroundColor(
                    Ui.background,
                )
                addView(
                    web,
                    FrameLayout.LayoutParams(
                        FrameLayout.LayoutParams.MATCH_PARENT,
                        FrameLayout.LayoutParams.MATCH_PARENT,
                    ),
                )
            }
        // WebView does not move its content for padding — the container takes the bars.
        Ui.applySystemInsets(
            frame,
            horizontalDp = 0,
            topDp = 0,
            bottomDp = 0,
        )
        setContentView(
            frame,
        )

        web.loadUrl(
            savedInstanceState?.getString(
                KEY_URL,
            ) ?: urlFor(
                intent.getStringExtra(
                    EXTRA_SECTION,
                ),
            ),
        )
    }

    override fun onBackPressed() {
        if (web.canGoBack()) {
            web.goBack()
        } else {
            @Suppress("DEPRECATION")
            super.onBackPressed()
        }
    }

    override fun onSaveInstanceState(
        outState: Bundle,
    ) {
        super.onSaveInstanceState(
            outState,
        )
        web.url?.let {
            outState.putString(
                KEY_URL,
                it,
            )
        }
    }

    override fun onDestroy() {
        web.destroy()
        super.onDestroy()
    }

    private class GuideClient(
        private val context: Context,
    ) : WebViewClient() {
        override fun shouldInterceptRequest(
            view: WebView,
            request: WebResourceRequest,
        ): WebResourceResponse? {
            val url =
                request.url
            if (url.host != ASSET_HOST) {
                return null
            }
            val path =
                url.path
                    .orEmpty()
                    .removePrefix(
                        "/assets/",
                    )
            // Only files of the guide folder; nothing else from the APK is served.
            if (!path.startsWith(GUIDE_DIR) || path.contains("..")) {
                return WebResourceResponse("text/plain", "utf-8", 404, "Not found", emptyMap(), null)
            }
            return runCatching {
                WebResourceResponse(
                    mimeFor(path),
                    "utf-8",
                    context.assets.open(path),
                )
            }.getOrElse {
                WebResourceResponse("text/plain", "utf-8", 404, "Not found", emptyMap(), null)
            }
        }

        override fun shouldOverrideUrlLoading(
            view: WebView,
            request: WebResourceRequest,
        ): Boolean {
            val url =
                request.url
            if (url.host == ASSET_HOST) {
                return false
            }
            // External links (if any) open in the browser.
            runCatching {
                context.startActivity(
                    Intent(
                        Intent.ACTION_VIEW,
                        url,
                    ).addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK,
                    ),
                )
            }
            return true
        }

        private fun mimeFor(
            path: String,
        ): String =
            when (path.substringAfterLast('.', "").lowercase()) {
                "html" -> "text/html"
                "css" -> "text/css"
                "js" -> "application/javascript"
                "png" -> "image/png"
                "webp" -> "image/webp"
                "svg" -> "image/svg+xml"
                else -> "application/octet-stream"
            }
    }

    companion object {
        private const val ASSET_HOST = "appassets.androidplatform.net"
        private const val GUIDE_DIR = "guide/"
        private const val START = "https://$ASSET_HOST/assets/guide/index.html"
        private const val KEY_URL = "url"
        private const val EXTRA_SECTION = "section"

        private fun urlFor(
            section: String?,
        ): String =
            if (section.isNullOrBlank()) START else "$START#$section"

        fun open(
            context: Context,
            section: String? = null,
        ) {
            context.startActivity(
                Intent(
                    context,
                    GuideActivity::class.java,
                ).apply {
                    section?.let {
                        putExtra(
                            EXTRA_SECTION,
                            it,
                        )
                    }
                },
            )
        }
    }
}
